#include <stdio.h>
#include <stdlib.h>
#include <math.h>

typedef struct { float x, y, z; } Vec;
typedef struct { Vec origin, direction; } Ray;
typedef struct { Vec point, normal; int hit; } Hit;
typedef struct { Vec center; float radius; } Sphere;

static Vec vsub(Vec a, Vec b) { Vec r = { a.x-b.x, a.y-b.y, a.z-b.z }; return r; }
static float vdot(Vec a, Vec b) { return a.x*b.x + a.y*b.y + a.z*b.z; }
static Vec vnorm(Vec a) {
    float len = sqrtf(a.x*a.x + a.y*a.y + a.z*a.z);
    Vec r = { a.x/len, a.y/len, a.z/len };
    return r;
}

static Hit sphere_intersect(Ray ray, Sphere s) {
    Hit h; h.hit = 0;
    Vec oc = vsub(ray.origin, s.center);
    float a = vdot(ray.direction, ray.direction);
    float b = 2.0f * vdot(ray.direction, oc);
    float c = vdot(oc, oc) - s.radius * s.radius;
    float disc = b*b - 4.0f*a*c;
    if (disc < 0.0f) return h;
    float t = (-b - sqrt((double)disc)) / (2.0f * a);
    if (t < 0.001f) {
        t = (-b + sqrt((double)disc)) / (2.0f * a);
        if (t < 0.001f) return h;
    }
    Vec p = { ray.origin.x + t*ray.direction.x,
              ray.origin.y + t*ray.direction.y,
              ray.origin.z + t*ray.direction.z };
    h.point = p;
    h.normal = vnorm(vsub(p, s.center));
    h.hit = 1;
    return h;
}

static int is_in_shadow(Vec point, Vec light, Sphere s) {
    Ray r; r.origin = point; r.direction = light;
    Hit h = sphere_intersect(r, s);
    return h.hit;
}

static Vec sky_color(Vec dir) {
    float t = 0.5f * (dir.y + 1.0f);
    Vec r = { (1.0f-t)*1.0f + t*0.5f, (1.0f-t)*1.0f + t*0.7f, (1.0f-t)*1.0f + t*1.0f };
    return r;
}

static Vec trace(Ray ray, Sphere sphere, Vec light) {
    Hit hs = sphere_intersect(ray, sphere);
    if (hs.hit) {
        Vec color = { 1.0f, 0.2f, 0.2f };
        float shade;
        if (is_in_shadow(hs.point, light, sphere)) {
            shade = 0.2f;
        } else {
            float intensity = (float)fmax(0.0, (double)vdot(hs.normal, light));
            shade = 0.2f + 0.8f * intensity;
        }
        Vec r = { color.x*shade, color.y*shade, color.z*shade };
        return r;
    }
    if (fabsf(ray.direction.y) > 1e-4f) {
        float t = (-1.5f - ray.origin.y) / ray.direction.y;
        if (t > 0.001f) {
            Vec p = { ray.origin.x + t*ray.direction.x,
                      ray.origin.y + t*ray.direction.y,
                      ray.origin.z + t*ray.direction.z };
            Vec normal = { 0.0f, 1.0f, 0.0f };
            int check = (int)((double)floorf(p.x) + (double)floorf(p.z));
            float base = (check & 1) ? 0.4f : 0.9f;
            float shade;
            if (is_in_shadow(p, light, sphere)) {
                shade = 0.2f;
            } else {
                float intensity = (float)fmax(0.0, (double)vdot(normal, light));
                shade = 0.2f + 0.8f * intensity;
            }
            Vec r = { base*shade, base*shade, base*shade };
            return r;
        }
    }
    return sky_color(ray.direction);
}

static Vec **allocate_image(int width, int height) {
    Vec **img = malloc(height * sizeof(Vec *));
    for (int y = 0; y < height; y++)
        img[y] = malloc(width * sizeof(Vec));
    return img;
}

static void free_image(Vec **img, int height) {
    for (int y = 0; y < height; y++)
        free(img[y]);
    free(img);
}

static void write_image(const char *filename, Vec **img, int width, int height) {
    FILE *f = fopen(filename, "w");
    if (!f) {
        fprintf(stderr, "Error: could not open file %s\n", filename);
        return;
    }
    fprintf(f, "P3\n%d %d\n255\n", width, height);
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            Vec c = img[y][x];
            int r = (int)((float)fmin(1.0, fmax(0.0, (double)c.x)) * 255.99f);
            int g = (int)((float)fmin(1.0, fmax(0.0, (double)c.y)) * 255.99f);
            int b = (int)((float)fmin(1.0, fmax(0.0, (double)c.z)) * 255.99f);
            fprintf(f, "%d %d %d\n", r, g, b);
        }
    }
    fclose(f);
    fprintf(stderr, "Wrote image to %s\n", filename);
}

int main(void) {
    int width = 800, height = 600;
    float aspect = (float)width / (float)height;

    fprintf(stderr, "Creating high-resolution image: %dx%d\n", width, height);
    fprintf(stderr, "This will be downsampled with ffmpeg after rendering\n");

    Vec light = vnorm((Vec){ 1.0f, 1.0f, -1.0f });
    Sphere sphere = { { 0.0f, -0.5f, -5.0f }, 1.0f };

    Vec **img = allocate_image(width, height);

    fprintf(stderr, "Rendering high-resolution image...\n");
    for (int y = 0; y < height; y++) {
        fprintf(stderr, "Progress: %.1f%%\n", 100.0f * y / height);
        for (int x = 0; x < width; x++) {
            float u = (float)x / (width - 1);
            float v = 1.0f - (float)y / (height - 1);
            Vec dir = { aspect * (2.0f*u - 1.0f), 2.0f*v - 1.0f, -1.0f };
            Ray ray; ray.origin = (Vec){ 0.0f, 0.0f, 0.0f }; ray.direction = vnorm(dir);
            img[y][x] = trace(ray, sphere, light);
        }
    }
    fprintf(stderr, "Rendering complete\n");

    write_image("image.ppm", img, width, height);
    free_image(img, height);
    fprintf(stderr, "Done.\n");
    return 0;
}

